/** Add one per-use checked Subtype decision inside an owned aggregate. */
export const ownedSubtypeReviewedIr = () => {
	const ir = ownedAggregateReviewedIr();
	const declaration = ir.declarations.find(item => item.name === "echoRecord");
	const payload = constructor => ({
		kind: "record", name: "Owned.Payload"
		, fields: [
			{ name: "count", refinement: { kind: "subtype", constructor } }
			, { name: "bytes", refinement: null }]
	});
	const bundle = constructor => ({
		kind: "record", name: "Owned.Bundle"
		, fields: [
			{ name: "primary", refinement: null }
			, { name: "spare", refinement: null }
			, { name: "peers", refinement: null }
			, { name: "history", refinement: null }
			, { name: "payload", refinement: payload(constructor) }]
	});
	declaration.source.extensions["lean-lang.org/refinements"] = {
		parameters: [bundle("Owned.checkedCount")]
		, result: bundle(null)
	};
	return ir;
};

const refinedNominalGraph = result => {
	const value = nominalGraph();
	value.types[0].fields.push({
		name: "count", projection: "Owned.Box.count"
		, type: {
			kind: "refinement"
			, base: { kind: "primitive", name: "nat", lean: "Nat", abi: heap }
			, predicate: { kind: "subtype", constructor: result ? null : "Owned.checkedCount" }
			, abi: heap
		}
	});
	return value;
};

test("owned graph validation admits directional Subtype leaves only at explicit sites", () => {
	const input = refinedNominalGraph(false), result = refinedNominalGraph(true);
	assert.equal(validateOwnedNativeType(input, policy, "parameter"), input);
	assert.equal(validateOwnedNativeType(result, policy, "result"), result);
	assert.throws(() => validateOwnedNativeType(input, policy), /top-level or structural-container/u);
	assert.throws(() => validateOwnedNativeType(input, policy, "result"), /invalid Subtype refinement/u);
	assert.throws(() => validateOwnedNativeType(result, policy, "parameter"), /invalid Subtype refinement/u);
	assert.throws(() => validateOwnedNativeType(input, policy, "callback"), /invalid owned refinement site/u);
});

test("owned models authenticate and retain per-use Subtype decisions without opening copied contracts", () => {
	const ir = ownedSubtypeReviewedIr(), before = structuredClone(ir);
	const declaration = ir.declarations.find(item => item.name === "echoRecord");
	assert.throws(() => declarationRefinements(declaration
		, declaration.source.extensions["lean-lang.org/refinements"], ir.types));
	const model = compileOwnedAggregateModel(ir);
	assert.deepEqual(ir, before);
	assert.deepEqual(model.declarations.find(item => item.name === "echoRecord").refinements
		, declaration.source.extensions["lean-lang.org/refinements"]);
	assert.equal(Object.isFrozen(model.declarations.find(item => item.name === "echoRecord").refinements), true);
	assert.throws(() => generateOwnedBindingCarriers({
		document: ir
		, sourceIdentity: {}
		, declarations: []
		, metadataSha256: "a".repeat(64)
	}), { code: "owned-refinements-unavailable" });
	const wrongInput = ownedSubtypeReviewedIr();
	wrongInput.declarations.find(item => item.name === "echoRecord")
		.source.extensions["lean-lang.org/refinements"].parameters[0]
		.fields[4].refinement.fields[0].refinement.constructor = null;
	assert.throws(() => compileOwnedAggregateModel(wrongInput), /Invalid declaration refinement|Refinement does not match/u);
	const wrongResult = ownedSubtypeReviewedIr();
	wrongResult.declarations.find(item => item.name === "echoRecord")
		.source.extensions["lean-lang.org/refinements"].result
		.fields[4].refinement.fields[0].refinement.constructor = "Owned.checkedCount";
	assert.throws(() => compileOwnedAggregateModel(wrongResult), /Invalid declaration refinement|Refinement does not match/u);
	const wrongField = ownedSubtypeReviewedIr();
	wrongField.declarations.find(item => item.name === "echoRecord")
		.source.extensions["lean-lang.org/refinements"].parameters[0].fields[4].name = "other";
	assert.throws(() => compileOwnedAggregateModel(wrongField), /Invalid declaration refinement|Refinement does not match/u);
});

test("owned review exports exact Subtype decisions for compiler reconciliation", () => {
	const document = ownedSubtypeReviewedIr(), review = capture(document);
	assert.deepEqual(validateReviewedOwnedSource(review), document);
	const selection = reviewedOwnedSourceSelection(review);
	const declaration = document.declarations.find(item => item.name === "echoRecord");
	assert.deepEqual(selection.contracts["Owned.echoRecord"].parameters[0].refinement
		, checkedRefinementSelection(declaration.source.extensions["lean-lang.org/refinements"].parameters[0]));
	assert.equal(Object.hasOwn(selection.contracts["Owned.echoRecord"], "result"), false);
	assert.equal(selection.contracts["Owned.echoRecord"].parameters[0].ownership, "borrow");
	const resultConstructor = structuredClone(document);
	resultConstructor.declarations.find(item => item.name === "echoRecord")
		.source.extensions["lean-lang.org/refinements"].result
		.fields[4].refinement.fields[0].refinement.constructor = "Owned.checkedCount";
	assert.throws(() => validateReviewedOwnedSource(capture(resultConstructor)), { code: "reviewed-ir-build-unsupported" });
});
